def _predict_secondary_gor_dssp(
    seq: str,
    radius: int = GOR_WINDOW_RADIUS,
) -> list[str]:
    """GOR IV secondary structure decision using the real DSSP-trained
    singlet/pair information tables (Garnier 1996; DECIPHER training).

    For each residue i:
        HEC[S] = background[S]
               - f1 * sum_{d=-8..+8} I(S; seq[i+d], d)
               + f2 * sum_{d in {-2,-1,+1,+2}} I(S; seq[i], seq[i+d], d)
    with f1 = GOR_IV_DSSP_SINGLET_WEIGHT (15/17) and f2 =
    GOR_IV_DSSP_PAIR_WEIGHT (60/17). The state with the maximum HEC
    score is assigned (argmax over H/E/C; the real GOR IV method has no
    decision constant / coil threshold).

    The window is truncated at sequence boundaries (no padding); only
    residues inside the valid range contribute.
    """
    n = len(seq)
    states = GOR_IV_DSSP_STATES
    f1 = GOR_IV_DSSP_SINGLET_WEIGHT
    f2 = GOR_IV_DSSP_PAIR_WEIGHT
    ss: list[str] = []
    for i in range(n):
        lo = max(0, i - radius)
        hi = min(n, i + radius + 1)
        hec: dict[str, float] = {s: GOR_IV_DSSP_BACKGROUND[s] for s in states}
        for j in range(lo, hi):
            d = j - i
            for s in states:
                hec[s] -= f1 * _GOR_IV_DSSP_SINGLET[(seq[j], d, s)]
        for d in GOR_PAIR_OFFSETS:
            j = i + d
            if 0 <= j < n:
                for s in states:
                    hec[s] += f2 * _GOR_IV_DSSP_PAIR[(seq[i], seq[j], d, s)]
        ss.append(max(states, key=hec.__getitem__))
    return ss
def predict_secondary_gor(
    sequence: str,
    method: str = "gor_iv_dssp",
) -> tuple[str, list[SecondaryStructureSegment]]:
    """GOR IV secondary structure prediction (17-residue window +
    singlet/pair information theory).

    Two parameterizations of the GOR method are available:

    - ``method="gor_iv_dssp"`` (default): the real GOR IV singlet/pair
      information tables trained on PDB/DSSP statistics (Garnier,
      Gibrat & Robson 1996; tables from the DECIPHER package, see
      :data:`_GOR_IV_DSSP_SINGLET` and :data:`_GOR_IV_DSSP_PAIR`).
      The prediction states are H/E/C and the state with the maximum
      information score is assigned (the real GOR IV method has no
      decision constant, i.e. no coil threshold). Expected accuracy
      ~64-65% (Q3), matching the real GOR IV method.
    - ``method="chou_fasman"`` (legacy): the previous implementation
      whose singlet/pair tables were derived from the Chou-Fasman
      propensity table; states are H/E/T with coil C as the threshold
      fallback. Kept for backward compatibility.

    Algorithm (common to both methods):
    1. Singlet information table: for each (residue r, window offset
       d in -8..+8, state S) store the log-odds information value
       I_singlet(S; r, d).
    2. Pair (dipeptide) information table: for the central residue i and
       its +/-1, +/-2 neighbors (d in {-2,-1,+1,+2}), store the pair
       information I_pair(S; r_i, r_{i+d}, d).
    3. For each residue i, accumulate the singlet information over the
       17-residue sliding window and the pair information over the
       +/-1, +/-2 neighbors and take the weighted combination.
    4. Assign the state with the maximum information (H/E/C for the
       DSSP-trained tables; H/E/T with the coil fallback for the legacy
       tables).
    5. The window is truncated at sequence boundaries (no padding).

    Args:
        sequence: amino acid sequence (single-letter codes)
        method: "gor_iv_dssp" (default; real DSSP-trained GOR IV
            tables) or "chou_fasman" (legacy Chou-Fasman-derived
            tables)

    Returns:
        (ss_string, segments), same format as :func:`predict_secondary`
        ss_string: per-residue SS state string ("H"/"E"/"C" for the
        DSSP-trained tables; "H"/"E"/"T"/"C" for the legacy tables)
        segments: list of SecondaryStructureSegment

    Raises:
        ValueError: if ``method`` is not a known GOR parameterization
    """
    if method not in ("gor_iv_dssp", "chou_fasman"):
        raise ValueError(
            f"unknown GOR method {method!r}; expected 'gor_iv_dssp' "
            "or 'chou_fasman'"
        )
    seq = _validate_sequence(sequence)
    n = len(seq)
    if n == 0:
        return "", []

    if method == "gor_iv_dssp":
        ss = _predict_secondary_gor_dssp(seq)
        segments = _build_ss_segments(seq, ss)
        return "".join(ss), segments

    # legacy Chou-Fasman-derived tables (kept reachable)
    radius = GOR_WINDOW_RADIUS
    alpha = GOR_SINGLET_ALPHA
    beta = GOR_PAIR_BETA
    ss = ["C"] * n
    for i in range(n):
        # truncate the window boundary (when part of the window extends
        # past the sequence, only take the valid range)
        lo = max(0, i - radius)
        hi = min(n, i + radius + 1)
        best_state = "C"
        best_info = GOR_COIL_THRESHOLD
        center = seq[i]
        for state in GOR_STATES:
            # singlet information: accumulate over the 17-residue
            # sliding window
            singlet_total = 0.0
            for j in range(lo, hi):
                singlet_total += _GOR_SINGLET_INFO[(seq[j], j - i, state)]
            # pair information: accumulate dipeptides of the central
            # residue with its +/-1, +/-2 neighbors
            pair_total = 0.0
            for d in GOR_PAIR_OFFSETS:
                j = i + d
                if 0 <= j < n:
                    pair_total += _GOR_PAIR_INFO[(center + seq[j], d, state)]
            total = alpha * singlet_total + beta * pair_total
            # strictly greater: on ties keep the prior (C or an earlier
            # state); the threshold filters out coil
            if total > best_info:
                best_info = total
                best_state = state
        ss[i] = best_state
    segments = _build_ss_segments(seq, ss)
    return "".join(ss), segments


# ============================================================================
# Kyte-Doolittle hydropathy curve
# ============================================================================

def hydropathy_profile(sequence: str, window: int = KD_WINDOW_SIZE) -> list[float]:
    """Compute the Kyte-Doolittle hydropathy curve (sliding-window
    average).

    Args:
        sequence: amino acid sequence
        window: sliding window size (default 9, classic value 7-11)

    Returns:
        per-residue window-averaged hydropathy values
        (length = len(sequence))
        positive values = hydrophobic regions, negative values =
        hydrophilic regions
    """
    seq = _validate_sequence(sequence)
    if not seq:
        return []
    if window < 1:
        raise ValueError(f"window must be >= 1, got {window}")
    raw = [KYTE_DOOLITTLE_SCALE[c] for c in seq]
    return _sliding_window_mean(raw, window)


def gravy(sequence: str) -> float:
    """Compute the GRAVY (Grand Average of Hydropathy) of a protein.

    I.e. the average Kyte-Doolittle hydropathy of the whole sequence.
    Positive values = overall hydrophobic protein; negative values =
    overall hydrophilic protein.
    Transmembrane proteins usually have GRAVY > 0; cytosolic proteins
    usually have GRAVY < 0.
    """
    seq = _validate_sequence(sequence)
    if not seq:
        return 0.0
    return sum(KYTE_DOOLITTLE_SCALE[c] for c in seq) / len(seq)


# ============================================================================
# Transmembrane helix prediction (KD + length thresholds)
# ============================================================================

def predict_transmembrane(
    sequence: str,
    window: int = TM_WINDOW_SIZE,
    threshold: float = TM_HYDROPATHY_THRESHOLD,
    min_length: int = TM_MIN_LENGTH,
    max_length: int = TM_MAX_LENGTH,
    extension_threshold: float = TM_EXTENSION_THRESHOLD,
) -> list[TransmembraneHelix]:
    """Predict transmembrane helices (simplified TMHMM).

    Algorithm (Krogh 2001 simplified, two-threshold method):
    1. Compute the sliding-window KD hydropathy curve.
    2. Find contiguous stretches with profile >= extension_threshold
       (low threshold) as candidate boundaries.
    3. Merge adjacent stretches (gap <= 3 residues).
    4. For each candidate stretch, check whether the peak (max profile)
       is >= threshold (high threshold, nucleation).
    5. Length limit: min_length <= L <= max_length + 5 (tolerates flanks).

    Benefit of the two-threshold method: the profile drops on both sides
    of a hydrophobic stretch due to window smoothing; using the low
    threshold for extension covers the full TM span, while the high
    threshold ensures the region is truly hydrophobic.

    Args:
        sequence: amino acid sequence
        window: sliding window size (default 19, covers a typical TM
                span)
        threshold: nucleation hydropathy threshold (default 1.6, KD 1982)
        min_length: minimum length (default 18, TMHMM standard)
        max_length: maximum length (default 30, typical TM upper bound)
        extension_threshold: extension threshold (default 0.8)

    Returns:
        list of TransmembraneHelix (sorted by position)
    """
    seq = _validate_sequence(sequence)
    n = len(seq)
    if n < min_length:
        return []

    profile = hydropathy_profile(seq, window=window)

    # 1. find contiguous stretches with profile >= extension_threshold
    #    (low-threshold extension)
    above_ext = [v >= extension_threshold for v in profile]
    segments: list[tuple[int, int]] = []
    i = 0
    while i < n:
        if above_ext[i]:
            start = i
            while i < n and above_ext[i]:
                i += 1
            end = i - 1
            segments.append((start, end))
        else:
            i += 1

    # 2. merge adjacent stretches (gap <= 3 residues)
    merged: list[tuple[int, int]] = []
    for seg in segments:
        if merged and seg[0] - merged[-1][1] <= 3:
            merged[-1] = (merged[-1][0], seg[1])
        else:
            merged.append(seg)

    # 3. check the peak + length for each stretch
    tms: list[TransmembraneHelix] = []
    for start, end in merged:
        peak = max(profile[start:end + 1])
        if peak < threshold:
            continue  # nucleation threshold not met
        length = end - start + 1
        if length < min_length:
            continue
        # truncate to max_length (take the center)
        if length > max_length + 5:
            center = (start + end) // 2
            half = max_length // 2
            new_start = max(start, center - half)
            new_end = min(end, center + half)
            start, end = new_start, new_end
        tm_seq = seq[start:end + 1]
        mean_hyd = sum(profile[start:end + 1]) / (end - start + 1)
        tms.append(TransmembraneHelix(
            start=start + 1, end=end + 1,
            length=end - start + 1,
            mean_hydropathy=mean_hyd,
            sequence=tm_seq,
        ))

    return tms


# ============================================================================
# Disorder region prediction
# ============================================================================

# ============================================================================
# IUPred-style disorder predictor (Dosztanyi et al. 2005 J Mol Biol
# 347:827-839; Dosztanyi 2018 Protein Sci 27:331-340)
#
# Energy predictor matrices and score histograms are the real IUPred2A
# parameter sets (long/short disorder), reproduced verbatim from the
# official IUPred2A distribution (Erdos & Dosztanyi 2020, elte.hu;
# https://github.com/doszilab/iupred2a).
#   - 20 x 20 energy predictor matrix P: P_ij connects the amino acid
#     composition vector to the per-residue energy
#         E_i = sum_j P_ij * c_j
#     where c_j is the frequency of amino acid j in the local
#     composition window (residues [i-100, i-2] + [i+2, i+100],
#     i.e. +/-1 neighbors excluded).
#   - the score is obtained from the smoothed energy via the empirical
#     energy histogram (survival distribution); scores are in [0, 1]
#     and residues with score > 0.5 are predicted disordered.
# ============================================================================

#: IUPred local composition window limits (residues excluded on both
#: sides of the central residue: [i - lc, i - 1] and [i + 1, i + uc])
IUPred_LOCAL_WINDOW_START = 1
#: IUPred long-disorder local composition window end (2-100 residues)
IUPred_LONG_LOCAL_WINDOW_END = 100
#: IUPred short-disorder local composition window end (2-25 residues)
IUPred_SHORT_LOCAL_WINDOW_END = 25
#: IUPred smoothing window (21-residue smoothing: +-10 around each
#: residue)
IUPred_SMOOTHING_WINDOW = 10
#: IUPred disorder threshold: residues with score > this are disordered
IUPred_DISORDER_THRESHOLD = 0.5
#: histogram boundary step offset (score clamped to 1/0 within 2 bins of
#: the histogram edges)
IUPred_HISTOGRAM_BOUNDARY_STEPS = 2
#: short-disorder edge compensation: positions outside the smoothing
#: window contribute this value (favoring disorder at the termini)
IUPred_SHORT_EDGE_COMPENSATION = -1.26
#: minimum length for a reported IUPred disorder region
IUPred_MIN_REGION_LENGTH = 10

#: IUPred2A long-disorder energy predictor matrix P (20 x 20), verbatim
