def _iupred_smooth(values: list[float], window: int) -> list[float]:
    """IUPred smoothing: sliding-window mean over [i-window, i+window],
    truncated at the sequence boundaries (i.e. +/-window residues, not
    the half-window used by :func:`_sliding_window_mean`)."""
    n = len(values)
    result = [0.0] * n
    for i in range(n):
        lo = max(0, i - window)
        hi = min(n, i + window + 1)
        chunk = values[lo:hi]
        result[i] = sum(chunk) / len(chunk) if chunk else 0.0
    return result


def iupred_scores(sequence: str, mode: str = "long") -> list[float]:
    """Per-residue IUPred-style disorder scores in [0, 1].

    Faithful port of the IUPred2A long/short disorder algorithm
    (Dosztanyi et al. 2005 J Mol Biol 347:827-839; Erdos & Dosztanyi
    2020, Current Protocols in Bioinformatics) using the verbatim
    IUPred2A energy matrices and histograms:

    1. Per-residue energy: E_i = sum_j P_ij * c_j, where c_j is the
       frequency of amino acid j in the local composition window
       (residues [i-uc, i-2] + [i+2, i+uc]; uc = 100 for long, 25 for
       short; the +/-1 neighbors are excluded).
    2. 21-residue smoothing (window IUPred_SMOOTHING_WINDOW = 10). The
       short mode additionally applies the IUPred2A terminal edge
       compensation (IUPred_SHORT_EDGE_COMPENSATION) favoring disorder
       at the chain termini.
    3. Scores in [0, 1] via the empirical energy histogram survival
       distribution; residues with score > 0.5 are predicted disordered.

    Args:
        sequence: amino acid sequence (single-letter codes)
        mode: "long" (default; global disorder, 2-100 residue window)
              or "short" (short disordered regions, 2-25 residue window,
              terminal disorder favored)

    Returns:
        per-residue disorder scores (length = len(sequence))

    Raises:
        ValueError: for an unknown ``mode`` or an empty sequence
    """
    seq = _validate_sequence(sequence)
    if not seq:
        raise ValueError("sequence must be non-empty")
    if mode == "long":
        uc = IUPred_LONG_LOCAL_WINDOW_END
        mtx = _IUPred_LONG_ENERGY_MATRIX
        hist = _IUPred_LONG_HISTOGRAM_SURVIVAL
        hmin = _IUPred_LONG_HISTOGRAM_MIN
        hmax = _IUPred_LONG_HISTOGRAM_MAX
        short = False
    elif mode == "short":
        uc = IUPred_SHORT_LOCAL_WINDOW_END
        mtx = _IUPred_SHORT_ENERGY_MATRIX
        hist = _IUPred_SHORT_HISTOGRAM_SURVIVAL
        hmin = _IUPred_SHORT_HISTOGRAM_MIN
        hmax = _IUPred_SHORT_HISTOGRAM_MAX
        short = True
    else:
        raise ValueError(
            f"unknown IUPred mode {mode!r}; expected 'long' or 'short'"
        )
    lc = IUPred_LOCAL_WINDOW_START
    wc = IUPred_SMOOTHING_WINDOW
    n = len(seq)
    hstep = (hmax - hmin) / len(hist)
    unweighted = [0.0] * n
    for i in range(n):
        window = (
            seq[max(0, i - uc):max(0, i - lc)] + seq[i + lc + 1:i + uc + 1]
        )
        if not window:
            continue
        win_len = len(window)
        for aa in set(window):
            unweighted[i] += (
                mtx[(seq[i], aa)] * (window.count(aa) / win_len)
            )
    if short:
        weighted = [0.0] * n
        for i in range(n):
            total = 0.0
            for k in range(i - wc, i + wc + 1):
                if 0 <= k < n:
                    total += unweighted[k]
                else:
                    total += IUPred_SHORT_EDGE_COMPENSATION
            weighted[i] = total / (2 * wc + 1)
    else:
        weighted = _iupred_smooth(unweighted, wc)
    scores = [0.0] * n
    boundary = IUPred_HISTOGRAM_BOUNDARY_STEPS
    for i, val in enumerate(weighted):
        if val <= hmin + boundary * hstep:
            scores[i] = 1.0
        elif val >= hmax - boundary * hstep:
            scores[i] = 0.0
        else:
            scores[i] = hist[int((val - hmin) * (1.0 / hstep))]
    return scores


def _iupred_regions(seq: str, scores: list[float]) -> list[DisorderRegion]:
    """Extract contiguous IUPred disorder regions (score >
    IUPred_DISORDER_THRESHOLD) with a minimum length of
    IUPred_MIN_REGION_LENGTH residues."""
    n = len(seq)
    regions: list[DisorderRegion] = []
    i = 0
    while i < n:
        if scores[i] > IUPred_DISORDER_THRESHOLD:
            start = i
            while i < n and scores[i] > IUPred_DISORDER_THRESHOLD:
                i += 1
            end = i - 1
            if end - start + 1 >= IUPred_MIN_REGION_LENGTH:
                dis_seq = seq[start:end + 1]
                mean_hyd = (
                    sum(KYTE_DOOLITTLE_SCALE[c] for c in dis_seq) / len(dis_seq)
                )
                regions.append(DisorderRegion(
                    start=start + 1, end=end + 1,
                    length=end - start + 1,
                    mean_hydropathy=mean_hyd,
                    sequence=dis_seq,
                ))
        else:
            i += 1
    return regions


def predict_disorder(
    sequence: str,
    window: int = DISORDER_WINDOW_SIZE,
    hydropathy_max: float = DISORDER_HYDROPATHY_MAX,
    charge_threshold: float = DISORDER_CHARGE_THRESHOLD,
    method: str = "chou_dunker",
    iupred_mode: str = "long",
) -> list[DisorderRegion]:
    """Predict intrinsic disorder regions.

    Two methods are available:

    - ``method="chou_dunker"`` (default, legacy): simplified Dunker 2001
      / Uversky 2000 charge-hydropathy heuristic. Disorder regions are
      characterized by low hydropathy (window-average KD <
      hydropathy_max, default -0.5), high charged-residue density
      ((K+R+H+D+E)/L > charge_threshold, default 0.2; total charge
      density is used because polyampholytes are also typical IDPs),
      and enrichment in Pro/Gly/Ser/Gln (disorder-promoting residues).
      This simplified version achieves ~70-75% accuracy, far below
      professional methods such as DISOPRED/IUPred (>85%). Behavior is
      unchanged from previous versions.
    - ``method="iupred"``: IUPred-style energy predictor (Dosztanyi et
      al. 2005): per-residue energy E_i = sum_j P_ij * c_j over the
      local composition window (2-100 residues), 21-residue smoothing,
      score in [0, 1] via the empirical energy histogram; residues with
      score > 0.5 are predicted disordered. Uses the real IUPred2A
      long/short energy matrices and histograms (see
      :func:`iupred_scores`).

    Args:
        sequence: amino acid sequence (single-letter codes)
        window: sliding window size for the legacy method (default 30)
        hydropathy_max: hydropathy upper limit for the legacy method
                        (default -0.5)
        charge_threshold: charged-residue fraction threshold for the
                          legacy method (default 0.2)
        method: "chou_dunker" (default, legacy) or "iupred"
        iupred_mode: for ``method="iupred"``, the IUPred parameter set
                     ("long" default or "short")

    Returns:
        list of DisorderRegion

    Raises:
        ValueError: if ``method`` or ``iupred_mode`` is unknown
    """
    if method == "iupred":
        seq = _validate_sequence(sequence)
        if not seq:
            return []
        scores = iupred_scores(seq, mode=iupred_mode)
        return _iupred_regions(seq, scores)
    if method != "chou_dunker":
        raise ValueError(
            f"unknown disorder method {method!r}; expected 'chou_dunker' "
            "or 'iupred'"
        )
    seq = _validate_sequence(sequence)
    n = len(seq)
    if n == 0:
        return []

    profile = hydropathy_profile(seq, window=window)

    # compute the charged-residue density at each position (fraction of
    # charged residues in the window)
    charged = set("KRHDE")
    charge_ratio = [0.0] * n
    half = window // 2
    for i in range(n):
        lo = max(0, i - half)
        hi = min(n, i + half + 1)
        chunk = seq[lo:hi]
        if not chunk:
            continue
        n_charged = sum(1 for c in chunk if c in charged)
        charge_ratio[i] = n_charged / len(chunk)

    # find disorder stretches (satisfying both low hydropathy and high
    # charge density)
    in_disorder = [
        profile[i] < hydropathy_max and charge_ratio[i] > charge_threshold
        for i in range(n)
    ]

    # extract contiguous stretches
    regions: list[DisorderRegion] = []
    i = 0
    while i < n:
        if in_disorder[i]:
            start = i
            while i < n and in_disorder[i]:
                i += 1
            end = i - 1
            # at least 10 residues
            if end - start + 1 >= 10:
                dis_seq = seq[start:end + 1]
                mean_hyd = sum(profile[start:end + 1]) / (end - start + 1)
                regions.append(DisorderRegion(
                    start=start + 1, end=end + 1,
                    length=end - start + 1,
                    mean_hydropathy=mean_hyd,
                    sequence=dis_seq,
                ))
        else:
            i += 1

    return regions

# ============================================================================
# Complete structure prediction report
# ============================================================================

def predict_structure(sequence: str) -> ProteinStructureReport:
    """Perform a complete structure prediction on a protein sequence.

    Includes:
    1. Chou-Fasman secondary structure
    2. Kyte-Doolittle hydropathy curve
    3. Transmembrane helix prediction
    4. Disorder region prediction
    5. Comprehensive report

    Args:
        sequence: amino acid sequence (single-letter codes)

    Returns:
        ProteinStructureReport
    """
    seq = _validate_sequence(sequence)
    n = len(seq)

    # secondary structure
    ss_string, ss_segments = predict_secondary(seq)
    helix_count = ss_string.count("H")
    sheet_count = ss_string.count("E")
    turn_count = ss_string.count("T")
    coil_count = ss_string.count("C")
    helix_frac = helix_count / n if n else 0.0
    sheet_frac = sheet_count / n if n else 0.0
    turn_frac = turn_count / n if n else 0.0
    coil_frac = coil_count / n if n else 0.0

    # hydropathy
    profile = hydropathy_profile(seq)
    mean_hyd = sum(KYTE_DOOLITTLE_SCALE[c] for c in seq) / n if n else 0.0
    gravy_val = gravy(seq)

    # transmembrane
    tm_helices = predict_transmembrane(seq)
    is_membrane = len(tm_helices) > 0

    # disorder
    disorder_regions = predict_disorder(seq)
    disorder_count = sum(r.length for r in disorder_regions)
    disorder_frac = disorder_count / n if n else 0.0

    # summary
    summary_parts = [
        f"length={n}",
        f"helix={helix_frac:.1%}",
        f"sheet={sheet_frac:.1%}",
        f"turn={turn_frac:.1%}",
        f"coil={coil_frac:.1%}",
        f"GRAVY={gravy_val:+.2f}",
        f"TM={len(tm_helices)}",
        f"disorder={disorder_frac:.1%}",
    ]
    if is_membrane:
        summary_parts.append("[membrane protein]")
    if disorder_frac > 0.3:
        summary_parts.append("[intrinsically disordered]")
    summary = " | ".join(summary_parts)

    return ProteinStructureReport(
        sequence=seq,
        length=n,
        secondary_structure=ss_string,
        ss_segments=ss_segments,
        helix_fraction=helix_frac,
        sheet_fraction=sheet_frac,
        turn_fraction=turn_frac,
        coil_fraction=coil_frac,
        hydropathy_profile=profile,
        mean_hydropathy=mean_hyd,
        transmembrane_helices=tm_helices,
        disorder_regions=disorder_regions,
        disorder_fraction=disorder_frac,
        is_membrane_protein=is_membrane,
        gravy=gravy_val,
        summary=summary,
    )


